async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const retry = document.getElementById('tRetry');
  const st = document.getElementById('tStatus');
  const sample = (t, label) => ({t, label, status: st.textContent, disabled: retry.hasAttribute('disabled'), display: getComputedStyle(retry).display, w: retry.getBoundingClientRect().width, visible: retry.checkVisibility ? retry.checkVisibility() : null});
  const out = [];
  document.getElementById('openTelemetry').click();
  out.push(sample(0, 'open+0'));
  await sleep(60); out.push(sample(60, 'open+60'));
  await sleep(200); out.push(sample(260, 'open+260'));
  await sleep(240); out.push(sample(500, 'open+500'));
  retry.click();
  out.push(sample(0, 'retry+0'));
  await sleep(60); out.push(sample(60, 'retry+60'));
  await sleep(700); out.push(sample(760, 'retry+760'));
  return out;
}

() => {
  const dlg = document.getElementById('dlg');
  return {status: JSON.stringify(document.getElementById('tStatus').textContent), volt: JSON.stringify(document.getElementById('tVolt').textContent), time: JSON.stringify(document.getElementById('tTime').textContent), strongs: [...dlg.querySelectorAll('strong')].map(s=>s.textContent), spanTexts: [...dlg.querySelectorAll('span')].map(s=>s.textContent), dlgAriaHidden: dlg.getAttribute('aria-hidden'), dlgCls: dlg.className};
}

() => {
  const dlg = document.getElementById('dlg');
  const close = document.getElementById('tClose');
  const before = {display: getComputedStyle(dlg).display, w: dlg.getBoundingClientRect().width};
  close.click();
  const after = {display: getComputedStyle(dlg).display, w: dlg.getBoundingClientRect().width, cls: dlg.className, ariaHidden: dlg.getAttribute('aria-hidden')};
  return {before, after};
}

